{"styles":{"blocks":{"core/button":{"variations":{"outline":{"spacing":{"padding":{"top":"calc(0.838rem - 1px)","right":"calc(2.5rem - 1px)","bottom":"calc(0.838rem - 1px)","left":"calc(2.5rem - 1px)"}}}}}},"color":{"text":"var(--wp--preset--color--foreground-alt)"},"elements":{"button":{"border":{"radius":"var(--wp--custom--elements--button--border--radius)"},"spacing":{"padding":{"top":"0.838rem","right":"2.5rem","bottom":"0.838rem","left":"2.5rem"}},"typography":{"fontSize":"1.0625rem","fontWeight":"var(--wp--custom--typography--font-weight--medium)","lineHeight":"inherit"}},"h1":{"typography":{"fontWeight":"400"}},"h2":{"typography":{"fontWeight":"400"}},"h3":{"typography":{"fontWeight":"400"}},"h4":{"typography":{"fontWeight":"400"}},"h5":{"typography":{"fontWeight":"400"}},"h6":{"typography":{"fontWeight":"400"}},"heading":{"color":{"text":"var(--wp--preset--color--foreground)"},"typography":{"fontFamily":"var(--wp--preset--font-family--marcellus)"}}},"typography":{"fontFamily":"var(--wp--preset--font-family--marcellus)","fontStyle":"normal","fontWeight":"400"},"css":".wp-block-heading { word-wrap: break-word; overflow-wrap: break-word; hyphens: auto;} .wp-block-heading:lang(zh), .wp-block-heading:lang(ja), .wp-block-heading:lang(ko), .wp-block-heading:lang(th), .wp-block-heading:lang(lo), .wp-block-heading:lang(my), .wp-block-heading:lang(km), .wp-block-heading:lang(ar), .wp-block-heading:lang(ur) { word-break: keep-all; }

@media (max-width: 782px) {
.mobile-reverse-order {
 flex-direction : column-reverse;
}
.mobile-reverse-order h3 {
text-align : left;
}

.leaves{
opacity: 0.13!important;
}
}

.z-index-99{
z-index : 99;
position : relative;
}

.position-absolute{
position:absolute!important;
z-index:100;
}

.navbar{
top:0; 
width : 100%;
}

.botbar{
position:absolute!important;
bottom:0; z-index:10;
width : 100%;
}

.leaves{
position:absolute!important;
bottom: -80px!important;
right: 0!important;
opacity: 0.4;
}

.wp-element-caption{
font-size : 17px !important;
}

.wp-block-pullquote{
margin-top : 40px !important;
margin-bottom : 0px !important;
}"},"settings":{"color":{"duotone":{"theme":[{"colors":["#014932","#395144"],"slug":"primary-and-secondary","name":"Primary and secondary"},{"colors":["#014932","#FFEFEA"],"slug":"primary-and-tertiary","name":"Primary and tertiary"},{"colors":["#395144","#014932"],"slug":"secondary-and-primary","name":"Secondary and primary"},{"colors":["#000000","#ffffff"],"slug":"foreground-and-background","name":"Foreground and background"},{"colors":["#014932","#000000"],"slug":"primary-foreground","name":"Primary and Foreground"}]},"palette":{"theme":[{"slug":"foreground","color":"#000000","name":"Foreground"},{"slug":"background","color":"#ffffff","name":"Background"},{"slug":"primary","color":"#014932","name":"Primary"},{"slug":"secondary","color":"#395144","name":"Secondary"},{"slug":"tertiary","color":"#FFEFEA","name":"Tertiary"},{"slug":"foreground-alt","color":"#333333","name":"foreground Alt"}],"custom":[{"color":"#707070","name":"Color 1","slug":"custom-color-1"}]}},"custom":{"elements":{"button":{"border":{"radius":"0.4rem"}}}},"shadow":{"presets":{"default":[{"name":"Natural","slug":"natural","shadow":"0px 2px 4px 0 rgba(0, 0, 0, 0.2)"},{"name":"Deep","slug":"deep","shadow":"12px 12px 50px rgba(0, 0, 0, 0.4)"},{"name":"Sharp","slug":"sharp","shadow":"6px 6px 0px rgba(0, 0, 0, 0.2)"},{"name":"Outlined","slug":"outlined","shadow":"6px 6px 0px -3px rgba(255, 255, 255, 1), 6px 6px rgba(0, 0, 0, 1)"},{"name":"Crisp","slug":"crisp","shadow":"6px 6px 0px rgba(0, 0, 0, 1)"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}
